import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();
  group.userData.type = 'pricing-title';

  // --- Text content ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find(i => i.role === 'headline') || items[0];

  // --- Plane (image background) ---
  const geometry = new PlaneGeometry(1.8, 1.125); // aspect ratio approx 1.6 (512/320)
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: false,
  });
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then(tex => {
      tex.colorSpace = ctx.THREE.SRGBColorSpace;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Text overlay ---
  if (headlineItem) {
    const fontSize = headlineItem.typography?.fontSize ?? 96;
    const textColor = '#e8ecf2'; // paper color from palette
    const text = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize,
      color: textColor,
      align: 'center',
    });
    // Position text slightly in front of plane
    text.position.z = 0.01;
    group.add(text);
  }

  // --- Event handlers (none) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    // Dispose text if it has cleanup (font atlas may expose it)
    if (group.children.length > 1) {
      const textChild = group.children[1];
      if (textChild.userData?.cleanup) {
        textChild.userData.cleanup();
      }
    }
    // No GSAP timelines to kill
  };

  return group;
}
